// src/core/utils.js

export function applyStyles(el, styles = {}) {
    Object.keys(styles).forEach(key => {
      el.style[key] = styles[key];
    });
  }
  
  export function getAttr(el, name, fallback = null) {
    const val = el.getAttribute(name);
    return val !== null ? val : fallback;
  }
  